<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require 'includes/toasts.php'; require_staff_or_admin($pdo);
$errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!csrf_check($_POST['csrf']??null)) $errors[]='Session expired. Refresh and try again.';
    elseif (($_POST['action']??'')==='add_group') {
        $name=trim((string)($_POST['group_name']??'')); $description=trim((string)($_POST['group_description']??''));
        if ($name===''||mb_strlen($name)>100||mb_strlen($description)>500) $errors[]='Enter a valid option group name and description.';
        else { try { $pdo->prepare('INSERT INTO menu_option_groups(name,description) VALUES(?,?)')->execute([$name,$description?:null]); $_SESSION['flash_success']='Option group added.'; header('Location: menu-option-management.php'); exit; } catch(Throwable $e) { $errors[]='That option group could not be added. It may already exist.'; } }
    } elseif (($_POST['action']??'')==='add_option') {
        $groupId=filter_var($_POST['option_group_id']??null,FILTER_VALIDATE_INT); $name=trim((string)($_POST['option_name']??'')); $sourceRaw=trim((string)($_POST['source_item_id']??'')); $sourceId=$sourceRaw===''?null:filter_var($sourceRaw,FILTER_VALIDATE_INT);
        if (!$groupId||($sourceRaw!==''&&!$sourceId)||($sourceId===null&&($name===''||mb_strlen($name)>255))||($sourceId!==null&&$name!=='')) $errors[]='Choose a group and provide either a choice name or source item.';
        else {
            if ($sourceId!==null) { $check=$pdo->prepare('SELECT 1 FROM menu_items WHERE item_id=?'); $check->execute([$sourceId]); if (!$check->fetchColumn()) $errors[]='Choose an existing menu item for this option.'; }
            if (!$errors) { try { $pdo->prepare('INSERT INTO menu_options(option_group_id,name,source_item_id) VALUES(?,?,?)')->execute([$groupId,$sourceId===null?$name:null,$sourceId]); $_SESSION['flash_success']='Option added.'; header('Location: menu-option-management.php'); exit; } catch(Throwable $e) { $errors[]='That option could not be added. Check for a duplicate choice.'; } }
        }
    } elseif (($_POST['action']??'')==='toggle_option') {
        $optionId=filter_var($_POST['option_id']??null,FILTER_VALIDATE_INT); $active=($_POST['is_available']??'')==='1'?0:1;
        if (!$optionId) $errors[]='Choose a valid option.';
        else { $pdo->prepare('UPDATE menu_options SET is_available=? WHERE option_id=?')->execute([$active,$optionId]); $_SESSION['flash_success']=$active?'Option activated.':'Option deactivated.'; header('Location: menu-option-management.php'); exit; }
    } else $errors[]='Choose a valid option management action.';
}
$groups=$pdo->query('SELECT option_group_id,name,description FROM menu_option_groups ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
$options=$pdo->query('SELECT o.option_id,o.option_group_id,o.name,o.source_item_id,o.is_available,g.name AS group_name,mi.name AS source_item_name FROM menu_options o JOIN menu_option_groups g ON g.option_group_id=o.option_group_id LEFT JOIN menu_items mi ON mi.item_id=o.source_item_id ORDER BY g.name,o.sort_order,COALESCE(o.name,mi.name)')->fetchAll(PDO::FETCH_ASSOC);
$items=$pdo->query('SELECT item_id,name FROM menu_items ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
$success=$_SESSION['flash_success']??null; unset($_SESSION['flash_success']); $pageTitle='Option management'; require 'includes/header.php'; render_toasts(array_merge(array_map(static fn($message)=>['kind'=>'danger','text'=>$message],$errors),$success?[['kind'=>'success','text'=>$success]]:[]));
?>
<main class="container py-5"><a class="btn btn-link auth-link px-0" href="menu-management.php">← Menu management</a><h1>Menu option management</h1><p class="text-secondary">Create reusable customization groups and choices. No menu choices are preloaded.</p>
<div class="row g-4"><section class="col-lg-5"><div class="card card-body"><h2 class="h5">Add option group</h2><form method="post" class="d-grid gap-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_group"><div><label class="form-label" for="group_name">Group name</label><input class="form-control" id="group_name" name="group_name" maxlength="100" required placeholder="Flavor, Drinks, Sides"></div><div><label class="form-label" for="group_description">Description (optional)</label><textarea class="form-control" id="group_description" name="group_description" maxlength="500" rows="2"></textarea></div><button class="btn btn-auth">Add group</button></form></div>
<div class="card card-body mt-4"><h2 class="h5">Add option choice</h2><form method="post" class="d-grid gap-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_option"><div><label class="form-label" for="option_group_id">Option group</label><select class="form-select" id="option_group_id" name="option_group_id" required><option value="">Choose a group</option><?php foreach($groups as $group): ?><option value="<?=(int)$group['option_group_id']?>"><?=e($group['name'])?></option><?php endforeach; ?></select></div><div><label class="form-label" for="option_name">Choice name</label><input class="form-control" id="option_name" name="option_name" maxlength="255" placeholder="Soy Garlic"></div><div><label class="form-label" for="source_item_id">Or link to a sellable menu item</label><select class="form-select" id="source_item_id" name="source_item_id"><option value="">Standalone choice</option><?php foreach($items as $item): ?><option value="<?=(int)$item['item_id']?>"><?=e($item['name'])?></option><?php endforeach; ?></select><div class="form-text">Choose a source item instead of entering a separate name to reuse its name.</div></div><button class="btn btn-auth" <?=$groups?'':'disabled'?>>Add choice</button></form></div></section>
<section class="col-lg-7"><div class="card card-body"><h2 class="h5">Option groups and choices</h2><?php if(!$groups): ?><p class="text-secondary mb-0">No option groups yet.</p><?php else: ?><?php foreach($groups as $group): $choices=array_values(array_filter($options,static fn($option)=>(int)$option['option_group_id']===(int)$group['option_group_id'])); ?><section class="border rounded p-3 mb-3"><h3 class="h6 mb-1"><?=e($group['name'])?></h3><?php if($group['description']): ?><p class="small text-secondary"><?=e($group['description'])?></p><?php endif; ?><?php if(!$choices): ?><p class="small text-secondary mb-0">No choices in this group yet.</p><?php else: ?><ul class="list-group list-group-flush"><?php foreach($choices as $choice): ?><li class="list-group-item px-0 d-flex justify-content-between align-items-center gap-3"><span><?=e($choice['name']?:$choice['source_item_name'])?><?php if(!$choice['is_available']): ?> <span class="badge text-bg-secondary">Inactive</span><?php endif; ?></span><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_option"><input type="hidden" name="option_id" value="<?=(int)$choice['option_id']?>"><input type="hidden" name="is_available" value="<?=(int)$choice['is_available']?>"><button class="btn btn-sm btn-outline-secondary"><?=$choice['is_available']?'Deactivate':'Activate'?></button></form></li><?php endforeach; ?></ul><?php endif; ?></section><?php endforeach; ?><?php endif; ?></div></section></div></main>
<?php require 'includes/footer.php'; ?>
